import itertools, json, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
L = list(L)
# Precompute possible triples (a,b,c) with a<b and a+b=c
triples = []
for a,b in itertools.combinations(L,2):
    s = a+b
    if s in L and s not in (a,b):
        triples.append((a,b,s))
# Backtracking to select 15 disjoint triples covering all numbers
used = set()
solution = []

def backtrack(idx, used, sol):
    if len(sol) == 15:
        if len(used) == 45:
            return sol
        return None
    if idx >= len(triples):
        return None
    # prune: if remaining numbers cannot fill required triples
    for i in range(idx, len(triples)):
        a,b,c = triples[i]
        if a in used or b in used or c in used:
            continue
        new_used = used | {a,b,c}
        res = backtrack(i+1, new_used, sol+[(a,b,c)])
        if res:
            return res
    return None

result = backtrack(0, set(), [])
if not result:
    print("No partition found.")
    sys.exit(1)
# Output triples
print("Found partition:\n")
for t in result:
    print(t)
# Emit witness line
witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":{"triples":result}}
print("WITNESS: " + json.dumps(witness))
